const fs=require('node:fs'),assert=require('node:assert/strict'),{JSDOM}=require('jsdom');
(async()=>{const html=fs.readFileSync('students/advanced-lab.html','utf8'),dom=new JSDOM(html,{url:'https://example.test/students/advanced-lab.html#force-diagram',runScripts:'outside-only',pretendToBeVisual:true}),w=dom.window,d=w.document,errors=[];w.addEventListener('error',e=>errors.push(String(e.error||e.message)));await new Promise(r=>w.addEventListener('load',r,{once:true}));for(const match of html.matchAll(/src="([^"?]+\.js)/g))w.eval(fs.readFileSync('students/'+match[1],'utf8'));const downloads=[];w.MT_STUDY_EXPORT.download=(name,text,type)=>downloads.push({name,text,type});const tick=()=>new Promise(r=>w.setTimeout(r,5));
assert.equal(d.getElementById('module').options.length,13);assert.equal(w.MT_INTERACTIVE_MODULES.length,45);
for(const id of Object.keys(w.MT_EDUCATION_MODEL_SCHEMAS)){const select=d.getElementById('module');select.value=id;select.dispatchEvent(new w.Event('change'));await tick();assert.ok(d.getElementById('model-error').hidden,id+': '+d.getElementById('model-error').textContent);assert.equal(w.MT_LEARNING_CYCLE_CONTEXT.read().id,id);assert.ok(d.querySelector('#learning-cycle'),'learning flow '+id);for(const option of [...d.getElementById('plot-selector').options]){d.getElementById('plot-selector').value=option.value;d.getElementById('plot-selector').dispatchEvent(new w.Event('change'));assert.ok(!/NaN|Infinity|undefined/.test(d.getElementById('model-chart').innerHTML),id+' finite chart');}for(const kind of ['json','csv','html','svg']){d.querySelector('[data-model-save="'+kind+'"]').click();const output=downloads.at(-1);assert.ok(output?.name.endsWith('.'+kind),id+' '+kind+' export');assert.ok(output.text.length>100);if(kind==='html')assert.ok(output.text.includes('study-snapshot'));}}
assert.deepEqual(errors,[]);dom.window.close();console.log(JSON.stringify({status:'PASS',models:13,exports:downloads.length,scope:'Actual advanced lab, all diagrams and exports, valid default models and shared learning contexts.'}));})().catch(e=>{console.error(e);process.exitCode=1});
